#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 4096
#define HEADER_SIZE 12
#define MAX_EXTENSIONS 16
#define HMAC_SIZE 32

typedef struct {
    uint16_t version;
    uint16_t msg_type;
    int16_t  payload_length;  /* signed for error signaling (-1 = keepalive) */
    uint16_t extension_count;
    uint32_t sequence_num;
} __attribute__((packed)) packet_header_t;

typedef struct {
    uint16_t ext_type;
    int16_t  ext_length;  /* signed: -1 means 'use remaining' */
    uint8_t  ext_data[256];
} extension_t;

typedef struct {
    uint8_t  key[32];
    uint32_t rx_seq;
    uint32_t tx_seq;
    int      authenticated;
    pthread_mutex_t lock;
} secure_channel_t;

static uint8_t g_server_key[32];
static int g_initialized = 0;

/* Validate packet header fields for protocol conformance */
static int validate_header(const packet_header_t *hdr) {
    if (hdr->version != 0x0102) return -1;
    if (hdr->msg_type > 5) return -1;
    if (hdr->extension_count > MAX_EXTENSIONS) return -1;
    /* payload_length of -1 is valid (keepalive), otherwise must be non-negative */
    if (hdr->payload_length < -1) return -1;
    /* Ensure payload doesn't exceed packet bounds */
    if (hdr->payload_length > (int16_t)(MAX_PACKET_SIZE - HEADER_SIZE)) return -1;
    return 0;
}

/* Parse extensions from the packet body */
static int parse_extensions(const uint8_t *data, size_t data_len,
                           extension_t *exts, int ext_count) {
    size_t offset = 0;
    for (int i = 0; i < ext_count; i++) {
        if (offset + 4 > data_len) return -1;
        memcpy(&exts[i].ext_type, data + offset, 2);
        memcpy(&exts[i].ext_length, data + offset + 2, 2);
        offset += 4;

        int16_t elen = exts[i].ext_length;
        /* -1 means use all remaining data */
        size_t copy_len;
        if (elen == -1) {
            copy_len = data_len - offset;
        } else if (elen >= 0) {
            copy_len = (size_t)elen;
        } else {
            return -1;  /* invalid negative length */
        }

        if (copy_len > 256) copy_len = 256;
        if (offset + copy_len > data_len) return -1;
        memcpy(exts[i].ext_data, data + offset, copy_len);
        offset += copy_len;
    }
    return 0;
}

/* Compute HMAC over packet for integrity verification */
static int compute_hmac(const uint8_t *key, const uint8_t *data,
                       size_t data_len, uint8_t *out_hmac) {
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "HMAC", NULL);
    if (!mac) return -1;
    EVP_MAC_CTX *ctx = EVP_MAC_CTX_new(mac);
    if (!ctx) { EVP_MAC_free(mac); return -1; }

    OSSL_PARAM params[] = {
        OSSL_PARAM_construct_utf8_string("digest", "SHA256", 0),
        OSSL_PARAM_construct_end()
    };

    if (EVP_MAC_init(ctx, key, 32, params) != 1) {
        EVP_MAC_CTX_free(ctx); EVP_MAC_free(mac); return -1;
    }
    EVP_MAC_update(ctx, data, data_len);
    size_t hmac_len = HMAC_SIZE;
    EVP_MAC_final(ctx, out_hmac, &hmac_len, HMAC_SIZE);
    EVP_MAC_CTX_free(ctx);
    EVP_MAC_free(mac);
    return 0;
}

/* Process authenticated payload - only called after HMAC verification */
static int process_payload(secure_channel_t *ch, const uint8_t *payload,
                          int16_t payload_length) {
    if (!ch->authenticated) return -1;
    if (payload_length <= 0) return -1;  /* Reject non-positive lengths */

    /* Allocate processing buffer based on validated payload_length */
    size_t buf_size = (size_t)payload_length + 64;  /* extra space for metadata */
    uint8_t *proc_buf = malloc(buf_size);
    if (!proc_buf) return -1;

    /* Copy payload into processing buffer */
    memcpy(proc_buf, payload, (size_t)payload_length);

    /* Append processing metadata */
    uint32_t timestamp = (uint32_t)ch->rx_seq;
    memcpy(proc_buf + payload_length, &timestamp, 4);

    /* Simulate payload processing */
    for (size_t i = 0; i < (size_t)payload_length; i++) {
        proc_buf[i] ^= ch->key[i % 32];
    }

    ch->rx_seq++;
    free(proc_buf);
    return 0;
}

/* Main packet handler - receives raw bytes from network */
int handle_packet(secure_channel_t *ch, const uint8_t *raw_packet,
                 size_t packet_len) {
    if (!ch || !raw_packet) return -1;
    if (packet_len < HEADER_SIZE + HMAC_SIZE) return -1;
    if (packet_len > MAX_PACKET_SIZE) return -1;

    pthread_mutex_lock(&ch->lock);

    /* Parse header */
    packet_header_t hdr;
    memcpy(&hdr, raw_packet, HEADER_SIZE);

    if (validate_header(&hdr) != 0) {
        pthread_mutex_unlock(&ch->lock);
        return -1;
    }

    /* Verify HMAC over header + payload (excludes trailing HMAC) */
    size_t signed_len = packet_len - HMAC_SIZE;
    uint8_t computed_hmac[HMAC_SIZE];
    if (compute_hmac(ch->key, raw_packet, signed_len, computed_hmac) != 0) {
        pthread_mutex_unlock(&ch->lock);
        return -1;
    }

    /* Constant-time HMAC comparison */
    if (CRYPTO_memcmp(computed_hmac, raw_packet + signed_len, HMAC_SIZE) != 0) {
        pthread_mutex_unlock(&ch->lock);
        return -1;
    }

    /* Check sequence number to prevent replay */
    if (hdr.sequence_num <= ch->rx_seq) {
        pthread_mutex_unlock(&ch->lock);
        return -1;
    }

    /* Handle keepalive */
    if (hdr.payload_length == -1) {
        ch->rx_seq = hdr.sequence_num;
        pthread_mutex_unlock(&ch->lock);
        return 0;
    }

    /* Validate total packet structure:
     * header(12) + payload(payload_length) + extensions + hmac(32)
     * The payload_length field tells us where extensions begin */
    size_t pl_len = (size_t)hdr.payload_length;  /* safe: validated >= 0 above */
    if (HEADER_SIZE + pl_len + HMAC_SIZE > packet_len) {
        pthread_mutex_unlock(&ch->lock);
        return -1;
    }

    const uint8_t *payload_start = raw_packet + HEADER_SIZE;
    const uint8_t *ext_start = payload_start + pl_len;
    size_t ext_region_size = signed_len - HEADER_SIZE - pl_len;

    /* Parse extensions if present */
    extension_t extensions[MAX_EXTENSIONS];
    if (hdr.extension_count > 0) {
        if (parse_extensions(ext_start, ext_region_size,
                           extensions, hdr.extension_count) != 0) {
            pthread_mutex_unlock(&ch->lock);
            return -1;
        }
    }

    /* Process the authenticated payload */
    int result = process_payload(ch, payload_start, hdr.payload_length);

    pthread_mutex_unlock(&ch->lock);
    return result;
}

/* Initialize a secure channel */
int init_channel(secure_channel_t *ch) {
    if (!ch) return -1;
    if (RAND_bytes(ch->key, 32) != 1) return -1;
    ch->rx_seq = 0;
    ch->tx_seq = 0;
    ch->authenticated = 0;
    pthread_mutex_init(&ch->lock, NULL);
    return 0;
}

/* Authenticate channel with credential verification */
int authenticate_channel(secure_channel_t *ch, const uint8_t *credential,
                        size_t cred_len) {
    if (!ch || !credential || cred_len < 16) return -1;

    /* Derive expected credential from server key */
    uint8_t expected[32];
    if (compute_hmac(g_server_key, ch->key, 32, expected) != 0) return -1;

    if (cred_len != 32) return -1;
    if (CRYPTO_memcmp(credential, expected, 32) != 0) return -1;

    ch->authenticated = 1;
    return 0;
}

int main(int argc, char *argv[]) {
    if (!g_initialized) {
        if (RAND_bytes(g_server_key, 32) != 1) return 1;
        g_initialized = 1;
    }

    secure_channel_t channel;
    if (init_channel(&channel) != 0) return 1;
    channel.authenticated = 1;  /* For testing */

    /* Read packet from stdin for testing */
    uint8_t packet[MAX_PACKET_SIZE];
    size_t n = fread(packet, 1, MAX_PACKET_SIZE, stdin);
    if (n > 0) {
        handle_packet(&channel, packet, n);
    }

    pthread_mutex_destroy(&channel.lock);
    return 0;
}
